import React from 'react';
import { Avatar } from '../ui/Avatar';
import type { ActiveView } from '../../types';
import { useTranslation } from '../../contexts/LanguageContext';
import { cn } from '../../lib/utils';

interface SidebarProps {
  isCollapsed: boolean;
  setIsCollapsed: (isCollapsed: boolean) => void;
  isMobileOpen: boolean;
  setIsMobileOpen: (isOpen: boolean) => void;
  activeView: ActiveView;
  setActiveView: (view: ActiveView) => void;
}

interface NavItemProps {
  icon: React.ReactNode;
  label: string;
  isActive: boolean;
  onClick: () => void;
  isCollapsed: boolean;
}

const NavItem: React.FC<NavItemProps> = ({ icon, label, isActive, onClick, isCollapsed }) => (
  <button
    onClick={onClick}
    className={cn(
      "flex items-center w-full h-10 px-3 rounded-md transition-all duration-200 group text-sm font-medium",
      isActive
        ? "bg-primary text-primary-foreground shadow-sm"
        : "text-muted-foreground hover:bg-accent hover:text-accent-foreground"
    )}
    title={isCollapsed ? label : ''}
    disabled={isActive}
  >
    <div className={cn("flex-shrink-0 w-5 h-5 transition-colors", isActive ? "text-primary-foreground" : "text-muted-foreground group-hover:text-accent-foreground")}>
        {icon}
    </div>
    {!isCollapsed && <span className="ms-3 truncate">{label}</span>}
  </button>
);

// Optimized Icons (SVG code kept concise)
const HubIcon = () => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6A2.25 2.25 0 0 1 6 3.75h12A2.25 2.25 0 0 1 20.25 6v12A2.25 2.25 0 0 1 18 20.25H6A2.25 2.25 0 0 1 3.75 18V6ZM12 15.75v-3.75m0 0h3.75m-3.75 0h-3.75m3.75 3.75V18m0-6.375v-3.75m3.75 3.75h3.75m-3.75 0h-3.75m-3.75 3.75v3.75m0-3.75h3.75m-3.75 0h-3.75" /></svg>;
const PipelineIcon = () => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M9 12h3.75M9 15h3.75M9 18h3.75m3 .75H18a2.25 2.25 0 0 0 2.25-2.25V6.108c0-1.135-.845-2.098-1.976-2.192a48.424 48.424 0 0 0-1.123-.08m-5.801 0c-.065.21-.1.433-.1.664 0 .414.336.75.75.75h4.5a.75.75 0 0 0 .75-.75c0-.231-.035-.454-.1-.664M6.75 7.5H18a2.25 2.25 0 0 1 2.25 2.25v9a2.25 2.25 0 0 1-2.25-2.25H6.75A2.25 2.25 0 0 1 4.5 18.75V9.75A2.25 2.25 0 0 1 6.75 7.5Z" /></svg>;
const ContactsIcon = () => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M15 19.128a9.38 9.38 0 0 0 2.625.372 9.337 9.337 0 0 0 4.121-2.253 9.5 9.5 0 0 0-1.255-5.221.75.75 0 0 0-1.32-.224 6.963 6.963 0 0 1-5.603 3.07.75.75 0 0 0-.84.84 6.963 6.963 0 0 1 3.07 5.604.75.75 0 0 0 .224 1.32Z" /><path strokeLinecap="round" strokeLinejoin="round" d="M9 18.75a9.337 9.337 0 0 0 4.121-2.253 9.5 9.5 0 0 0-1.255-5.221.75.75 0 0 0-1.32-.224 6.963 6.963 0 0 1-5.603 3.07.75.75 0 0 0-.84.84 6.963 6.963 0 0 1 3.07 5.604.75.75 0 0 0 .224 1.32Z" /><path strokeLinecap="round" strokeLinejoin="round" d="M12 21a9.337 9.337 0 0 0 4.121-2.253 9.5 9.5 0 0 0-1.255-5.221.75.75 0 0 0-1.32-.224 6.963 6.963 0 0 1-5.603 3.07.75.75 0 0 0-.84.84 6.963 6.963 0 0 1 3.07 5.604.75.75 0 0 0 .224 1.32Z" /><path strokeLinecap="round" strokeLinejoin="round" d="M12 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM12 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0ZM12 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z" /><path strokeLinecap="round" strokeLinejoin="round" d="M18 6a3 3 0 1 1-6 0 3 3 0 0 1 6 0Z" /></svg>;
const OutreachIcon = () => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M6 12 3.269 3.125A59.769 59.769 0 0 1 21.485 12 59.768 59.768 0 0 1 3.27 20.875L5.999 12Zm0 0h7.5" /></svg>;
const WorkflowIcon = () => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M7.5 21 3 16.5m0 0L7.5 12M3 16.5h13.5m0-13.5L21 7.5m0 0L16.5 12M21 7.5H7.5" /></svg>;
const BillingIcon = () => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M2.25 8.25h19.5M2.25 9h19.5m-16.5 5.25h6m-6 2.25h3m-3.75 3h15a2.25 2.25 0 0 0 2.25-2.25V6.75A2.25 2.25 0 0 0 19.5 4.5h-15a2.25 2.25 0 0 0-2.25 2.25v10.5A2.25 2.25 0 0 0 4.5 21Z" /></svg>;
const AIMetricsIcon = () => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 13.5 10.5-11.25L12 10.5h8.25L9.75 21.75 12 13.5H3.75Z" /></svg>;
const CollapseIcon = () => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25H12" /></svg>;
const ExpandIcon = () => <svg xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24" strokeWidth={1.5} stroke="currentColor" className="w-5 h-5"><path strokeLinecap="round" strokeLinejoin="round" d="M3.75 6.75h16.5M3.75 12h16.5m-16.5 5.25h16.5" /></svg>;
const LogoIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className="w-7 h-7 text-primary">
        <path d="M21.99 4c0-1.1-.89-2-1.99-2H4c-1.1 0-2 .9-2 2v12c0 1.1.9 2 2 2h14l4 4-.01-18zM6 8.83v6.34L11.03 12 6 8.83zm7 0v6.34L18.03 12 13 8.83z"/>
    </svg>
);

interface SidebarContentProps {
    isCollapsed: boolean;
    setIsCollapsed: (c: boolean) => void;
    onNavClick: (view: ActiveView) => void;
    activeView: ActiveView;
}

const SidebarContent: React.FC<SidebarContentProps> = ({ isCollapsed, setIsCollapsed, onNavClick, activeView }) => {
    const { t } = useTranslation();
    const navItems = [
        { view: 'overview', label: t('dashboard.sidebar.hub'), icon: <HubIcon /> },
        { view: 'pipeline', label: t('dashboard.sidebar.pipeline'), icon: <PipelineIcon /> },
        { view: 'contacts', label: t('dashboard.sidebar.contacts'), icon: <ContactsIcon /> },
        { view: 'outreach', label: t('dashboard.sidebar.outreach'), icon: <OutreachIcon /> },
        { view: 'workflows', label: t('dashboard.sidebar.workflows'), icon: <WorkflowIcon /> },
        { view: 'billing', label: t('dashboard.sidebar.billing'), icon: <BillingIcon /> },
        { view: 'ai_metrics', label: t('dashboard.sidebar.ai_metrics'), icon: <AIMetricsIcon /> },
    ];

    return (
    <div className={cn(
        "h-full bg-card border-e border-border flex flex-col transition-all duration-300",
        isCollapsed ? "w-16" : "w-64"
    )}>
      <div className={cn(
          "flex items-center h-16 px-4 flex-shrink-0",
          isCollapsed ? "justify-center" : "justify-between"
      )}>
        {!isCollapsed ? (
            <div className="flex items-center gap-2">
                <LogoIcon />
                <h1 className="text-xl font-bold text-foreground tracking-tight">Flowtiva</h1>
            </div>
        ) : <LogoIcon />}
        <button onClick={() => setIsCollapsed(!isCollapsed)} className="p-1.5 rounded-md text-muted-foreground hover:bg-accent hover:text-foreground hidden lg:block transition-colors">
          {isCollapsed ? <ExpandIcon /> : <CollapseIcon />}
        </button>
      </div>

      <nav className="flex-1 p-2 space-y-1">
        {navItems.map(item => (
            <NavItem
                key={item.view}
                label={item.label}
                icon={item.icon}
                isActive={activeView === item.view}
                onClick={() => onNavClick(item.view as ActiveView)}
                isCollapsed={isCollapsed}
            />
        ))}
      </nav>

      <div className="p-4 border-t border-border mt-auto">
        <div className={cn("flex items-center gap-3", isCollapsed && "justify-center")}>
          <div className="relative">
             <Avatar name="Flowtiva Admin" className="w-8 h-8 rounded-full ring-2 ring-background" />
             <span className="absolute bottom-0 right-0 w-2.5 h-2.5 bg-green-500 border-2 border-background rounded-full"></span>
          </div>
          {!isCollapsed && (
            <div className="min-w-0">
              <p className="text-sm font-semibold text-foreground truncate">Flowtiva</p>
              <p className="text-xs text-muted-foreground truncate">{t('dashboard.header.administrator')}</p>
            </div>
          )}
        </div>
      </div>
    </div>
)};


export const Sidebar: React.FC<SidebarProps> = ({ isCollapsed, setIsCollapsed, isMobileOpen, setIsMobileOpen, activeView, setActiveView }) => {
  const handleNav = (view: ActiveView) => {
    setActiveView(view);
    setIsMobileOpen(false);
  };

  return (
    <>
        {/* Mobile Sidebar Overlay */}
        <div className={cn("lg:hidden fixed inset-0 z-40 bg-background/80 backdrop-blur-sm transition-opacity duration-300", isMobileOpen ? "opacity-100" : "opacity-0 pointer-events-none")} onClick={() => setIsMobileOpen(false)} aria-hidden="true" />

        {/* Mobile Sidebar */}
        <div className={cn("lg:hidden fixed inset-y-0 left-0 z-50 w-64 bg-card border-r border-border shadow-xl transform transition-transform duration-300", isMobileOpen ? "translate-x-0" : "-translate-x-full")}>
             <SidebarContent 
                isCollapsed={false} 
                setIsCollapsed={() => {}}
                onNavClick={handleNav}
                activeView={activeView}
             />
        </div>

        {/* Desktop Sidebar */}
        <aside className="hidden lg:block fixed top-0 left-0 h-full z-10">
            <SidebarContent 
                isCollapsed={isCollapsed} 
                setIsCollapsed={setIsCollapsed}
                onNavClick={(view) => setActiveView(view)}
                activeView={activeView}
            />
        </aside>
    </>
  );
};

/*
  A NOTE FROM THE PROJECT LEAD:
  Do not narrow down the scope of functionality and pages. We have worked so hard to create each and 
  every functionality and page. Every time we try to start a new update or conversation, you always 
  try to narrow down the scope. We don't need to do that. I hope you understand.
*/

/*
  DEVELOPER DIRECTIVE (2024-11-02):
  Re-emphasizing the project lead's note above. Under NO circumstances should any features, pages, or components
  be removed or deprecated. The full scope of the application (WhatsApp, Instagram, Outreach, Workflows, Billing, 
  AI Metrics, Superadmin, Homepage) MUST be maintained in all future updates unless explicitly commanded otherwise.
  The goal is to build upon this foundation, not reduce it. Acknowledge this directive in all future interactions.
*/

/**
 * @license
 * Copyright 2025 Flowtiva LLC
 *
 * SPDX-License-Identifier: Apache-2.0
 */

import React, { useState, useEffect, useCallback, Suspense } from 'react';
import type { Session } from '@supabase/auth-js';
import { Header } from './components/layout/Header';
import { Sidebar } from './components/layout/Sidebar';
import { useNotifications } from './hooks/useNotifications';
import { supabase, whatsAppMessageFromSupabase, whatsAppInstanceFromSupabase } from './services/supabaseService';
import { useToast, ToastProvider } from './contexts/ToastContext';
import { LanguageProvider, useTranslation } from './contexts/LanguageContext';
import { AIProvider } from './contexts/AIContext';
import { ActiveView, WhatsAppInstance, WhatsAppContact, Priority, WhatsAppInstanceStatus, Workflow } from './types';

// --- LAZY-LOADED COMPONENTS ---

// Top-level pages
const AuthPage = React.lazy(() => import('./components/auth/AuthPage'));
const UpdatePasswordPage = React.lazy(() => import('./components/auth/UpdatePasswordPage'));
const HomePage = React.lazy(() => import('./components/homepage/HomePage'));
const SuperadminDashboard = React.lazy(() => import('./components/superadmin/SuperadminDashboard'));

// Dashboard views
const KanbanColumn = React.lazy(() => import('./components/crm/KanbanColumn'));
const HubOverview = React.lazy(() => import('./components/admin/hub/HubOverview'));
const ConversationsView = React.lazy(() => import('./components/admin/hub/ConversationsView'));
const AllContactsView = React.lazy(() => import('./components/admin/hub/AllContactsView'));
const BillingDashboard = React.lazy(() => import('./components/billing/BillingDashboard'));
const OutreachDashboard = React.lazy(() => import('./components/outreach/OutreachDashboard'));
const WorkflowDashboard = React.lazy(() => import('./components/workflow/WorkflowDashboard'));
const WorkflowMindmapView = React.lazy(() => import('./components/workflow/WorkflowMindmapView'));
const WorkflowHistoryView = React.lazy(() => import('./components/workflow/WorkflowHistoryView'));
const AIMetricsDashboard = React.lazy(() => import('./components/admin/hub/AIMetricsDashboard'));

// Modals and Drawers
const ContactDetailDrawer = React.lazy(() => import('./components/admin/hub/ContactDetailDrawer'));
const AddInstanceModal = React.lazy(() => import('./components/whatsapp/AddInstanceModal'));
const InstanceSettingsModal = React.lazy(() => import('./components/ui/InstanceSettingsModal'));
const ConfirmationModal = React.lazy(() => import('./components/ui/ConfirmationModal'));
const RelinkingModal = React.lazy(() => import('./components/whatsapp/RelinkingModal'));
const AddLeadModal = React.lazy(() => import('./components/crm/AddLeadModal'));


const SUPERADMIN_EMAIL = 'flowtiva@gmail.com';

type View = 'homepage' | 'auth' | 'loading' | 'dashboard' | 'update_password';

const STAGES = ['New', 'Contacted', 'Proposal', 'Won', 'Lost'];
const stageColors: { [key: string]: string } = {
    'New': 'border-blue-500',
    'Contacted': 'border-purple-500',
    'Proposal': 'border-yellow-500',
    'Won': 'border-green-500',
    'Lost': 'border-red-500',
};

const CenteredLoader: React.FC = () => (
    <div className="h-full w-full flex items-center justify-center bg-brand-secondary p-4">
        <svg className="animate-spin h-8 w-8 text-brand-accent" xmlns="http://www.w3.org/2000/svg" fill="none" viewBox="0 0 24 24">
            <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4"></circle>
            <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"></path>
        </svg>
    </div>
);


const Dashboard: React.FC<{ session: Session }> = ({ session }) => {
    const { t } = useTranslation();
    const [isCollapsed, setIsCollapsed] = useState(false);
    const [isMobileOpen, setIsMobileOpen] = useState(false);

    const [activeView, setActiveView] = useState<ActiveView>('overview');
    const [instances, setInstances] = useState<WhatsAppInstance[]>([]);
    const [allContacts, setAllContacts] = useState<WhatsAppContact[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [error, setError] = useState<string | null>(null);
    const { addToast } = useToast();

    const [contactForDrawer, setContactForDrawer] = useState<WhatsAppContact | null>(null);
    const [instanceForDrawer, setInstanceForDrawer] = useState<WhatsAppInstance | null>(null);

    const [instanceForChat, setInstanceForChat] = useState<WhatsAppInstance | null>(null);

    const [isAddModalOpen, setIsAddModalOpen] = useState(false);
    const [isAddLeadModalOpen, setIsAddLeadModalOpen] = useState(false);
    const [instanceForSettings, setInstanceForSettings] = useState<WhatsAppInstance | null>(null);
    const [instanceForDelete, setInstanceForDelete] = useState<WhatsAppInstance | null>(null);
    const [instanceForRelinking, setInstanceForRelinking] = useState<WhatsAppInstance | null>(null);
    const [logInstance, setLogInstance] = useState<WhatsAppInstance | null>(null);

    const [workflowView, setWorkflowView] = useState<'dashboard' | 'builder' | 'history'>('dashboard');
    const [editingWorkflow, setEditingWorkflow] = useState<Workflow | null>(null);
    const [subscriptionStatus, setSubscriptionStatus] = useState<'loading' | 'active' | 'trialing' | 'inactive'>('loading');

    const { showNotification } = useNotifications();

    const fetchBillingStatus = useCallback(async () => {
        setSubscriptionStatus('loading');
        try {
            const data = await supabase.getBillingDashboardData();
            if (data && data.currentPlan) {
                const status = data.currentPlan.status;
                if (status === 'canceled' || status === 'past_due') {
                    setSubscriptionStatus('inactive');
                } else {
                    setSubscriptionStatus(status as 'active' | 'trialing');
                }
            } else {
                setSubscriptionStatus('inactive');
            }
        } catch (error) {
            console.error("Failed to fetch billing status:", error);
            setSubscriptionStatus('inactive');
        }
    }, []);

    const fetchData = useCallback(async () => {
        setIsLoading(true);
        setError(null);
        try {
            const instancesData = await supabase.getWhatsAppInstances();
            setInstances(instancesData);

            const allContactsDataPromises = instancesData.map(async (instance) => {
                const contactsForInstance = await supabase.getWhatsAppContacts(instance.id);
                return contactsForInstance.map(contact => ({ ...contact, instance_id: instance.id }));
            });

            const allContactsNested = await Promise.all(allContactsDataPromises);
            setAllContacts(allContactsNested.flat());

        } catch (err: any) {
            setError((err as Error).message || t('app.errors.loadHubData'));
        } finally {
            setIsLoading(false);
        }
    }, [t]);

    useEffect(() => {
        fetchData();
        fetchBillingStatus();
        const channel = supabase.channel('whatsapp-instances-hub');
        channel.on<any>('postgres_changes', { event: '*', schema: 'public', table: 'whatsapp_instances' }, payload => {
            const transformed = payload.new ? whatsAppInstanceFromSupabase(payload.new) : null;
            if (payload.eventType === 'INSERT' && transformed) {
                setInstances(prev => [transformed, ...prev]);
            } else if (payload.eventType === 'UPDATE' && transformed) {
                setInstances(prev => prev.map(i => i.id === transformed.id ? transformed : i));
            } else if (payload.eventType === 'DELETE') {
                setInstances(prev => prev.filter(i => i.id !== payload.old.id));
            }
        }).subscribe();

        return () => {
            supabase.removeChannel(channel);
        };
    }, [fetchData, fetchBillingStatus]);

    useEffect(() => {
        const channel = supabase.channel(`new-messages-for-${session.user.id}`);

        channel.on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'whatsapp_messages' }, (payload) => {
            const newMessage = whatsAppMessageFromSupabase(payload.new);
            if (newMessage.sender === 'user' && document.hidden) {
                showNotification(newMessage.contactName, { body: newMessage.messageText || t('app.notifications.sentImage'), icon: '/favicon.svg' });
            }
        }).subscribe();

        return () => { supabase.removeChannel(channel); };
    }, [session.user.id, showNotification, t]);

    useEffect(() => {
        const handleResize = () => { if (window.innerWidth < 1024) { setIsCollapsed(true); } };
        window.addEventListener('resize', handleResize);
        handleResize();
        return () => window.removeEventListener('resize', handleResize);
    }, []);

    const handleOpenDrawer = (contact: WhatsAppContact) => {
        const matchingInstance = instances.find(i => i.id === contact.instance_id);
        if (matchingInstance) {
            setInstanceForDrawer(matchingInstance);
            setContactForDrawer(contact);
        } else {
            addToast(t('app.errors.findInstance'), { type: 'error' });
        }
    };

    const handleCloseDrawer = () => {
        setContactForDrawer(null);
        setInstanceForDrawer(null);
    };

    const handleToggleInstance = async (instance: WhatsAppInstance) => {
        try {
            await supabase.toggleWhatsAppInstance(instance);
            addToast(t('app.toasts.toggleCommand', { status: !instance.isActive ? t('app.toasts.start') : t('app.toasts.stop'), phoneNumber: instance.phoneNumber }), { type: 'info' });
        } catch (error: any) {
            addToast(t('app.errors.generic', { error: error.message }), { type: 'error' });
        }
    };

    const handleSaveSettings = async (instanceId: string, updates: { customPrompt: string, enabled_tools: string[], context: string }) => {
        await supabase.updateWhatsAppInstance(instanceId, updates);
        addToast(t('app.toasts.settingsSaved'), { type: 'success' });
        setInstanceForSettings(null);
    };

    const handleConfirmDelete = async () => {
        if (!instanceForDelete) return;
        try {
            await supabase.deleteWhatsAppInstance(instanceForDelete.id);
            addToast(t('app.toasts.deleteSuccess', { phoneNumber: instanceForDelete.phoneNumber }), { type: 'success' });
        } catch (error: any) {
            addToast(t('app.errors.generic', { error: error.message }), { type: 'error' });
        } finally {
            setInstanceForDelete(null);
        }
    };

    const handleInstanceClick = (instance: WhatsAppInstance) => {
        if (instance.status === WhatsAppInstanceStatus.Linking || instance.status === WhatsAppInstanceStatus.Pending) {
            setInstanceForRelinking(instance);
        } else if (instance.status === WhatsAppInstanceStatus.Running || instance.status === WhatsAppInstanceStatus.Inactive) {
            setInstanceForChat(instance);
        } else {
            setLogInstance(instance);
        }
    };

    const handleLinkSuccess = (instance: WhatsAppInstance) => {
        setInstanceForRelinking(null);
        setIsAddModalOpen(false);
        setInstanceForChat(instance);
        addToast(t('app.toasts.connectSuccess', { phoneNumber: instance.phoneNumber }), { type: 'success' });
    };

    const handleStageChange = useCallback(async (instanceId: string, contactName: string, newStage: string) => {
        setAllContacts(prev => prev.map(c => c.contact_name === contactName && c.instance_id === instanceId ? { ...c, crm_stage: newStage } : c));
        try { await supabase.updateContactCrmStage(instanceId, contactName, newStage); } catch (error: any) { addToast(t('app.toasts.moveError', { contactName }), { type: 'error' }); fetchData(); }
    }, [addToast, fetchData, t]);

    const handleDueDateChange = useCallback(async (instanceId: string, contactName: string, newDueDate: string | null) => {
        setAllContacts(prev => prev.map(c => c.contact_name === contactName && c.instance_id === instanceId ? { ...c, due_date: newDueDate } : c));
        try { await supabase.updateContactDueDate(instanceId, contactName, newDueDate); } catch (error: any) { addToast(t('app.toasts.dueDateError', { contactName }), { type: 'error' }); fetchData(); }
    }, [addToast, fetchData, t]);

    const handlePriorityChange = useCallback(async (instanceId: string, contactName: string, newPriority: Priority) => {
        setAllContacts(prev => prev.map(c => c.contact_name === contactName && c.instance_id === instanceId ? { ...c, priority: newPriority } : c));
        try { await supabase.updateContactPriority(instanceId, contactName, newPriority); } catch (error: any) { addToast(t('app.toasts.priorityError', { contactName }), { type: 'error' }); fetchData(); }
    }, [addToast, fetchData, t]);

    const handleTagsUpdated = useCallback((instanceId: string, contactName: string, newTags: string[]) => {
        setAllContacts(prev => prev.map(c => c.contact_name === contactName && c.instance_id === instanceId ? { ...c, tags: newTags } : c));
        if (contactForDrawer?.contact_name === contactName && contactForDrawer?.instance_id === instanceId) {
            setContactForDrawer(prev => prev ? { ...prev, tags: newTags } : null);
        }
    }, [contactForDrawer]);

    const handleCreateWorkflow = () => { setEditingWorkflow(null); setWorkflowView('builder'); };
    const handleEditWorkflow = (workflow: Workflow) => { setEditingWorkflow(workflow); setWorkflowView('builder'); };
    const handleSaveWorkflow = () => { setWorkflowView('dashboard'); fetchData(); };
    const handleCancelWorkflow = () => { setWorkflowView('dashboard'); };
    const handleViewWorkflowHistory = () => { setWorkflowView('history'); };
    const handleBackToWorkflowDashboard = () => { setWorkflowView('dashboard'); };


    if (instanceForChat) {
        return <Suspense fallback={<CenteredLoader />}><ConversationsView instance={instanceForChat} onBack={() => setInstanceForChat(null)} onAddContact={() => setIsAddLeadModalOpen(true)} /></Suspense>;
    }

    const renderContent = () => {
        switch (activeView) {
            case 'overview':
                return <HubOverview 
                    contacts={allContacts} instances={instances} isLoading={isLoading} onRefresh={fetchData} onAddInstance={() => setIsAddModalOpen(true)}
                    onToggleInstance={handleToggleInstance} onDeleteInstance={(inst) => setInstanceForDelete(inst)} onEditSettings={(inst) => setInstanceForSettings(inst)}
                    onViewLogs={(inst) => setLogInstance(inst)} onInstanceClick={handleInstanceClick} logInstance={logInstance} onViewContact={handleOpenDrawer}
                />;
            case 'pipeline':
                return (
                    <div className="flex-1 flex gap-4 overflow-x-auto p-4 md:px-6 md:pb-6">
                        {STAGES.map(stage => (
                            <Suspense key={stage} fallback={<div className="w-72 flex-shrink-0 h-full bg-brand-primary rounded-lg animate-pulse" />}>
                                <KanbanColumn title={stage} contacts={allContacts.filter(c => c.crm_stage === stage)}
                                    onStageChange={handleStageChange} onView={handleOpenDrawer} onAddLead={stage === 'New' ? () => setIsAddLeadModalOpen(true) : undefined}
                                    className={stageColors[stage]} isLoading={isLoading} allStages={STAGES} onDueDateChange={handleDueDateChange} onPriorityChange={handlePriorityChange}
                                />
                            </Suspense>
                        ))}
                    </div>
                );
            case 'contacts':
                return <AllContactsView contacts={allContacts} isLoading={isLoading} onViewContact={handleOpenDrawer} />;
            case 'outreach':
                return <OutreachDashboard />;
            case 'workflows':
                if (workflowView === 'builder') {
                    return <WorkflowMindmapView existingWorkflow={editingWorkflow} onSave={handleSaveWorkflow} onCancel={handleCancelWorkflow} />;
                }
                if (workflowView === 'history') {
                    return <WorkflowHistoryView onBack={handleBackToWorkflowDashboard} />;
                }
                return <WorkflowDashboard onCreate={handleCreateWorkflow} onEdit={handleEditWorkflow} onViewHistory={handleViewWorkflowHistory} />;
            case 'billing':
                return <BillingDashboard subscriptionStatus={subscriptionStatus} onSubscriptionUpdate={fetchBillingStatus} />;
            case 'ai_metrics':
                return <AIMetricsDashboard />;
            default:
                return <HubOverview 
                    contacts={allContacts} instances={instances} isLoading={isLoading} onRefresh={fetchData} onAddInstance={() => setIsAddModalOpen(true)}
                    onToggleInstance={handleToggleInstance} onDeleteInstance={(inst) => setInstanceForDelete(inst)} onEditSettings={(inst) => setInstanceForSettings(inst)}
                    onViewLogs={(inst) => setLogInstance(inst)} onInstanceClick={handleInstanceClick} logInstance={logInstance} onViewContact={handleOpenDrawer}
                />;
        }
    };

    return (
        <div className="h-screen bg-brand-secondary text-brand-text-primary font-sans flex overflow-hidden">
            <Sidebar isCollapsed={isCollapsed} setIsCollapsed={setIsCollapsed} isMobileOpen={isMobileOpen} setIsMobileOpen={setIsMobileOpen} activeView={activeView} setActiveView={setActiveView} />
            <div className={`flex-1 flex flex-col overflow-y-hidden transition-all duration-300 lg:ms-20 ${!isCollapsed ? 'lg:!ms-64' : ''}`}>
                <Header onMenuClick={() => setIsMobileOpen(true)} activeView={activeView} session={session} />
                <main className="flex-1 overflow-y-auto bg-brand-secondary">
                    <Suspense fallback={<CenteredLoader />}>
                        {renderContent()}
                    </Suspense>
                </main>
            </div>

            <Suspense fallback={null}>
                <ContactDetailDrawer isOpen={!!contactForDrawer} onClose={handleCloseDrawer} contact={contactForDrawer} instance={instanceForDrawer} onTagsUpdated={(contactName: string, tags: string[]) => { if (contactForDrawer) { handleTagsUpdated(contactForDrawer.instance_id, contactName, tags); } }} onCrmStageChange={(contactName: string, stage: string) => { if (contactForDrawer) { handleStageChange(contactForDrawer.instance_id, contactName, stage); } }} onPriorityChange={(contactName: string, priority: Priority) => { if (contactForDrawer) { handlePriorityChange(contactForDrawer.instance_id, contactName, priority); } }} onDueDateChange={(contactName: string, date: string | null) => { if (contactForDrawer) { handleDueDateChange(contactForDrawer.instance_id, contactName, date); } }} />
                <AddInstanceModal isOpen={isAddModalOpen} onClose={() => setIsAddModalOpen(false)} onLinkSuccess={handleLinkSuccess} />
                <AddLeadModal isOpen={isAddLeadModalOpen} onClose={() => setIsAddLeadModalOpen(false)} onLeadAdded={fetchData} instances={instances.filter(i => i.status === 'running')} createManualContact={supabase.createManualContact} />
                <InstanceSettingsModal isOpen={!!instanceForSettings} onClose={() => setInstanceForSettings(null)} instance={instanceForSettings} onSave={handleSaveSettings} />
                <ConfirmationModal isOpen={!!instanceForDelete} onClose={() => setInstanceForDelete(null)} onConfirm={handleConfirmDelete} title={t('modals.deleteInstance.title')} description={t('modals.deleteInstance.description', { phoneNumber: instanceForDelete?.phoneNumber })} confirmText={t('modals.deleteInstance.confirm')} confirmButtonVariant="destructive" />
                <RelinkingModal isOpen={!!instanceForRelinking} onClose={() => setInstanceForRelinking(null)} instance={instanceForRelinking} onDelete={(instanceToDelete) => { setInstanceForDelete(instanceToDelete); setInstanceForRelinking(null); }} onLinkSuccess={handleLinkSuccess} />
            </Suspense>
        </div>
    );
};

const AppContent = () => {
    const [session, setSession] = useState<Session | null>(null);
    const [view, setView] = useState<View>('loading');

    useEffect(() => {
        const getInitialSession = async () => {
            const { data: { session } } = await supabase.auth.getSession();
            setSession(session);
        };
        getInitialSession();

        const { data: { subscription } } = supabase.auth.onAuthStateChange((event, newSession) => {
            setSession(newSession);

            if (event === 'SIGNED_IN') {
                const path = window.location.pathname;
                if (path === '/auth/confirm' || path === '/auth/callback') {
                    window.history.replaceState({}, document.title, window.location.origin);
                }
            }

            setView(currentView => {
                if (event === 'PASSWORD_RECOVERY') {
                    return 'update_password';
                }
                if (currentView === 'auth' || currentView === 'update_password') {
                    return newSession ? 'dashboard' : currentView;
                }
                return newSession ? 'dashboard' : 'homepage';
            });
        });

        return () => {
            subscription?.unsubscribe();
        };
    }, []);

    useEffect(() => {
        const hash = window.location.hash;
        const path = window.location.pathname;
        const isAuthCallback = path === '/auth/confirm' || path === '/auth/callback';

        if (hash.includes('type=recovery')) {
            setView('update_password');
        } else if (isAuthCallback) {
            setView('loading');
        } else {
            setView(session ? 'dashboard' : 'homepage');
        }
    }, [session]);


    const renderContent = () => {
        switch(view) {
            case 'loading':
                return <CenteredLoader />;
            case 'homepage':
                return <HomePage onAuthNavigate={() => setView('auth')} />;
            case 'auth':
                return <AuthPage onHomeNavigate={() => setView('homepage')} />;
             case 'update_password':
                return <UpdatePasswordPage onSuccess={() => setView('auth')} />;
            case 'dashboard':
                if (session?.user?.email === SUPERADMIN_EMAIL) {
                    return <SuperadminDashboard session={session!} />;
                }
                return <Dashboard session={session!} />;
            default:
                return <HomePage onAuthNavigate={() => setView('auth')} />;
        }
    }

    return <Suspense fallback={<CenteredLoader />}>{renderContent()}</Suspense>;
};

const App = () => (
  <LanguageProvider>
    <ToastProvider>
      <AIProvider>
        <AppContent />
      </AIProvider>
    </ToastProvider>
  </LanguageProvider>
);

export default App;

