type DemoStep = 
  | 'idle' 
  | 'user_typing' 
  | 'msg_sent' 
  | 'ai_processing' 
  | 'crm_updating' 
  | 'ai_typing' 
  | 'ai_reply' 
  | 'complete';

interface ChatMessage {
    id: string;
    sender: 'user' | 'ai';
    text: string;
    time?: string;
    status: 'sent' | 'delivered' | 'read';
}

