            await new Promise(r => { timer = setTimeout(r, 400); });
            setCrmData(prev => ({ ...prev, intent: config.crm.intent }));
            await new Promise(r => { timer = setTimeout(r, 400); });
            setCrmData(prev => ({ ...prev, stage: config.crm.stage }));
            await new Promise(r => { timer = setTimeout(r, 400); });
            setCrmData(prev => ({ ...prev, tag: config.crm.tag }));

