                { ...prev[prev.length - 1], status: 'read' }, // Mark user msg as read
                { id: 'new_2', sender: 'ai', text: config.reply, time: replyTime, status: 'read' }
            ]);
            setStep('ai_reply');

            await new Promise(r => { timer = setTimeout(r, 4000); });
            setStep('complete'); 
        };

        sequence();
        return () => clearTimeout(timer);
    }, []);


