  return (
    <header className="sticky top-0 z-30 h-16 glass border-b border-border/40 px-6 flex items-center justify-between gap-6 transition-all duration-300">

      {/* Left: Title & Mobile Menu */}
      <div className="flex items-center gap-4 min-w-[200px]">
